import sys
def load_ppm(path):
    with open(path,'rb') as f: data=f.read()
    parts=[]; i=0
    while len(parts)<4:
        while data[i] in b' \t\n\r': i+=1
        if data[i]==ord('#'):
            while data[i]!=ord('\n'): i+=1
            continue
        j=i
        while data[i] not in b' \t\n\r': i+=1
        parts.append(data[j:i]); i+=1
    return int(parts[1]),int(parts[2]),data[i:]

w,h,pix=load_ppm(sys.argv[1])
def px(x,y):
    if 0<=x<w and 0<=y<h:
        o=(y*w+x)*3
        return pix[o],pix[o+1],pix[o+2]
    return None

def is_btn_gray(r,g,b):
    return r is not None and abs(r-g)<15 and abs(g-b)<15 and 165<=r<=215

visited=[[False]*w for _ in range(h)]
blobs=[]
for y in range(0,h):
    for x in range(0,w):
        if visited[y][x]: continue
        r,g,b=px(x,y)
        if not is_btn_gray(r,g,b):
